const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

let first = true;
let n = 0;
let linesRead = 0;
let depth = 0;
let valid = true;

rl.on('line', (line) => {
  if (first) {
    n = parseInt(line.trim(), 10);
    first = false;
    return;
  }
  linesRead++;
  for (const ch of line) {
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth < 0) valid = false;
    }
  }
  if (linesRead === n) {
    rl.close();
    console.log(valid && depth === 0 ? 'S' : 'N');
  }
});
